120	    /// What was hashed (file path, glob, command).
121	    pub target: String,
122	    /// New hash value.
123	    pub hash: String,
124	    /// Scope ("project" or "workflow:<name>").
125	    pub scope: String,
126	    /// What kind of change occurred.
127	    pub change: BaselineChange,
128	}
129	
130	/// Manages baseline hashes for change check comparisons.
131	///
132	/// The store reads/writes YAML files in a snapshots directory.
133	/// Each step+config combination gets its own file.
134	pub struct SnapshotStore {
135	    /// Directory where snapshot files are stored.
136	    dir: PathBuf,
137	    /// In-memory cache of loaded snapshot data.
138	    cache: HashMap<String, SnapshotData>,
139	    /// Pending baseline changes for event emission.
140	    pending_events: Vec<BaselineEvent>,
141	}
142	
143	impl SnapshotStore {
144	    /// Create a new store backed by the given directory.
145	    pub fn new(dir: impl Into<PathBuf>) -> Self {
146	        Self {
147	            dir: dir.into(),
148	            cache: HashMap::new(),
149	            pending_events: Vec::new(),
150	        }
151	    }
152	
153	    /// Create an empty in-memory store not backed by any directory.
154	    ///
155	    /// Useful when check evaluation doesn't need snapshot storage
156	    /// (e.g., evaluating presence or execution checks only).
157	    /// Change checks evaluated against this store will always get
158	    /// `None` baselines (indeterminate results).
159	    pub fn empty() -> Self {
160	        Self {
161	            dir: PathBuf::new(),
162	            cache: HashMap::new(),
163	            pending_events: Vec::new(),
164	        }
165	    }
166	
167	    /// Load or create a snapshot store for a project.
168	    ///
169	    /// Uses `~/.bivvy/projects/{project_hash}/snapshots/` as the storage
170	    /// directory, matching the state store's project isolation scheme.
171	    pub fn load_for_project(project_id: &crate::state::ProjectId) -> Self {
172	        let dir = crate::sys::home_dir()
173	            .unwrap_or_else(|| PathBuf::from("~"))
174	            .join(".bivvy")
175	            .join("projects")
176	            .join(project_id.hash())
177	            .join("snapshots");
178	        Self::new(dir)
179	    }
180	
181	    /// Get the baseline hash for a change check.
182	    ///
183	    /// The `baseline_name` parameter selects which baseline to compare against:
184	    /// - `"_last_run"` for `each_run` baseline config
185	    /// - `"_first_run"` for `first_run` baseline config
186	    /// - A named slug for `snapshot:<slug>` baseline config
187	    pub fn get_baseline(&mut self, key: &SnapshotKey, baseline_name: &str) -> Option<String> {
188	        self.ensure_loaded(key);
189	        let filename = key.filename();
190	        self.cache
191	            .get(&filename)
192	            .and_then(|data| data.baselines.get(baseline_name))
193	            .map(|entry| entry.hash.clone())
194	    }
195	
196	    /// Record a new baseline after successful step execution.
197	    ///
198	    /// Returns [`BaselineChange`] indicating whether this was a new baseline
199	    /// or an update to an existing one (with the old hash).
200	    pub fn record_baseline(
201	        &mut self,
202	        key: &SnapshotKey,
203	        baseline_name: &str,
204	        hash: String,
205	        target: String,
206	    ) -> BaselineChange {
207	        self.ensure_loaded(key);
208	        let filename = key.filename();
209	        let data = self.cache.entry(filename).or_insert_with(|| SnapshotData {
210	            step: key.step_name.clone(),
211	            scope: key.scope.clone(),
212	            baselines: HashMap::new(),
213	        });
214	
215	        let change = match data.baselines.get(baseline_name) {
216	            None => BaselineChange::Established,
217	            Some(existing) if existing.hash == hash => BaselineChange::Unchanged,
218	            Some(existing) => BaselineChange::Updated {
219	                old_hash: existing.hash.clone(),
220	            },
221	        };
222	
223	        if !matches!(change, BaselineChange::Unchanged) {
224	            self.pending_events.push(BaselineEvent {
225	                step: key.step_name.clone(),
226	                target: target.clone(),
227	                hash: hash.clone(),
228	                scope: key.scope.clone(),
229	                change: change.clone(),
230	            });
231	        }
232	
233	        data.baselines.insert(
234	            baseline_name.to_string(),
235	            BaselineEntry {
236	                hash,
237	                captured_at: now_iso8601(),
238	                target,
239	            },
240	        );
241	
242	        change
243	    }
244	
245	    /// Drain pending baseline change events.
246	    ///
247	    /// Returns all baseline changes that occurred since the last drain.
248	    /// The orchestrator calls this after check evaluation to emit
249	    /// `BaselineEstablished` / `BaselineUpdated` events.
250	    pub fn drain_events(&mut self) -> Vec<BaselineEvent> {
251	        std::mem::take(&mut self.pending_events)
252	    }
253	
254	    /// Capture a named snapshot.
255	    pub fn capture_named(&mut self, key: &SnapshotKey, slug: &str, hash: String, target: String) {
256	        self.record_baseline(key, slug, hash, target);
257	    }
258	
259	    /// List all named snapshots (excludes internal baselines like _last_run).
260	    pub fn list_named(&mut self) -> Vec<SnapshotInfo> {
261	        self.load_all();
262	        let mut result = Vec::new();
263	        for data in self.cache.values() {
264	            for (name, entry) in &data.baselines {
265	                if !name.starts_with('_') {
266	                    result.push(SnapshotInfo {
267	                        slug: name.clone(),
268	                        step: data.step.clone(),
269	                        target: entry.target.clone(),
270	                        hash: entry.hash.clone(),
271	                        captured_at: entry.captured_at.clone(),
272	                    });
273	                }
274	            }
275	        }
276	        result.sort_by(|a, b| a.slug.cmp(&b.slug));
277	        result
278	    }
279	
280	    /// Delete a named snapshot.
281	    pub fn delete_named(&mut self, slug: &str) -> bool {
282	        self.load_all();
283	        let mut found = false;
284	        for data in self.cache.values_mut() {
285	            if data.baselines.remove(slug).is_some() {
286	                found = true;
287	            }
288	        }
289	        found
290	    }
291	
292	    /// Save all modified data to disk.
293	    pub fn save(&self) -> std::io::Result<()> {
294	        std::fs::create_dir_all(&self.dir)?;
295	        for (filename, data) in &self.cache {
296	            let path = self.dir.join(filename);
297	            let yaml = serde_yaml::to_string(data).map_err(std::io::Error::other)?;
298	            std::fs::write(path, yaml)?;
299	        }
300	        Ok(())
301	    }
302	
303	    /// Load snapshot data for a key if not already cached.
304	    fn ensure_loaded(&mut self, key: &SnapshotKey) {
305	        let filename = key.filename();
306	        if self.cache.contains_key(&filename) {
307	            return;
308	        }
309	        let path = self.dir.join(&filename);
310	        if path.exists() {
311	            if let Ok(contents) = std::fs::read_to_string(&path) {
312	                if let Ok(data) = serde_yaml::from_str::<SnapshotData>(&contents) {
313	                    self.cache.insert(filename, data);
314	                    return;
315	                }
316	            }
317	        }
318	        // Initialize empty
319	        self.cache.insert(
320	            filename,
321	            SnapshotData {
322	                step: key.step_name.clone(),
323	                scope: key.scope.clone(),
324	                baselines: HashMap::new(),
325	            },
326	        );
327	    }
328	
329	    /// Load all snapshot files from disk.
330	    fn load_all(&mut self) {
331	        if !self.dir.exists() {
332	            return;
333	        }
334	        if let Ok(entries) = std::fs::read_dir(&self.dir) {
335	            for entry in entries.flatten() {
336	                let path = entry.path();
337	                if path.extension().is_some_and(|e| e == "yml") {
338	                    let filename = path
339	                        .file_name()
340	                        .unwrap_or_default()
341	                        .to_string_lossy()
342	                        .to_string();
343	                    if self.cache.contains_key(&filename) {
344	                        continue;
345	                    }
346	                    if let Ok(contents) = std::fs::read_to_string(&path) {
347	                        if let Ok(data) = serde_yaml::from_str::<SnapshotData>(&contents) {
348	                            self.cache.insert(filename, data);
349	                        }
350	                    }
351	                }
352	            }
353	        }
354	    }
355	}
