214	// === Glob pattern matching ===
215	
216	/// Match files against a glob pattern and return matching paths.
217	///
218	/// Supports `*` (any non-separator chars), `**` (recursive directory match),
219	/// and `?` (single char). The pattern should be an absolute path with glob
220	/// characters (e.g., `/path/to/project/*.rb`).
221	pub fn glob(pattern: &str) -> Result<Vec<PathBuf>, String> {
222	    let pattern = pattern.replace('\\', "/");
223	
224	    // Find where the first wildcard character appears
225	    let first_wild = pattern.find(['*', '?', '[']).unwrap_or(pattern.len());
226	
227	    // Base directory is everything up to the last '/' before the first wildcard
228	    let base_end = pattern[..first_wild].rfind('/').map(|i| i + 1).unwrap_or(0);
229	    let base_dir = if base_end > 0 {
230	        PathBuf::from(&pattern[..base_end])
231	    } else {
232	        PathBuf::from(".")
233	    };
234	
235	    if !base_dir.exists() {
236	        return Ok(Vec::new());
237	    }
238	
239	    let rel_pattern = &pattern[base_end..];
240	
241	    // Walk the directory tree and collect all files
242	    let mut all_paths = Vec::new();
243	    walk_dir_recursive(&base_dir, &mut all_paths);
244	
245	    // Match each path against the relative pattern
246	    let mut matches: Vec<PathBuf> = Vec::new();
247	    for path in all_paths {
248	        let rel_path = path
249	            .strip_prefix(&base_dir)
250	            .unwrap_or(&path)
251	            .to_string_lossy()
252	            .replace('\\', "/");
253	
254	        if glob_match_path(rel_pattern, &rel_path) {
255	            matches.push(path);
256	        }
257	    }
258	
259	    matches.sort();
260	    Ok(matches)
261	}
262	
263	fn walk_dir_recursive(dir: &Path, results: &mut Vec<PathBuf>) {
264	    let entries = match std::fs::read_dir(dir) {
265	        Ok(e) => e,
266	        Err(_) => return,
267	    };
268	    for entry in entries.flatten() {
269	        let path = entry.path();
270	        results.push(path.clone());
271	        if path.is_dir() {
272	            walk_dir_recursive(&path, results);
273	        }
274	    }
275	}
276	
277	/// Match a glob pattern against a path string.
278	///
279	/// Both pattern and path use `/` as separator. The pattern may contain
280	/// `*` (matches non-separator chars), `**` (matches across separators),
281	/// and `?` (matches single non-separator char).
282	fn glob_match_path(pattern: &str, path: &str) -> bool {
283	    let pat_parts: Vec<&str> = pattern.split('/').collect();
284	    let path_parts: Vec<&str> = path.split('/').collect();
285	    match_components(&pat_parts, &path_parts)
286	}
287	
288	fn match_components(patterns: &[&str], paths: &[&str]) -> bool {
289	    if patterns.is_empty() {
290	        return paths.is_empty();
291	    }
292	
293	    if patterns[0] == "**" {
294	        // `**` matches zero or more path components
295	        for i in 0..=paths.len() {
296	            if match_components(&patterns[1..], &paths[i..]) {
297	                return true;
298	            }
299	        }
300	        return false;
301	    }
302	
303	    if paths.is_empty() {
304	        return false;
305	    }
306	
307	    // Match first component, then recurse
308	    match_segment(patterns[0], paths[0]) && match_components(&patterns[1..], &paths[1..])
309	}
310	
311	/// Match a single path segment against a glob pattern segment.
312	///
313	/// Handles `*` (any chars) and `?` (single char).
314	fn match_segment(pattern: &str, text: &str) -> bool {
315	    match_bytes(pattern.as_bytes(), text.as_bytes())
316	}
317	
318	fn match_bytes(pattern: &[u8], text: &[u8]) -> bool {
319	    match (pattern.first(), text.first()) {
320	        (None, None) => true,
321	        (Some(b'*'), _) => {
322	            // Try matching zero chars, or advance text by one
323	            match_bytes(&pattern[1..], text)
324	                || (!text.is_empty() && match_bytes(pattern, &text[1..]))
325	        }
326	        (Some(b'?'), Some(_)) => match_bytes(&pattern[1..], &text[1..]),
327	        (Some(&a), Some(&b)) if a == b => match_bytes(&pattern[1..], &text[1..]),
328	        _ => false,
329	    }
330	}
