    #[test]
    fn session_id_without_sess_prefix_still_works() {
        let dir = TempDir::new().unwrap();
        let logger =
            EventLogger::new(dir.path(), "custom_id_123", RetentionPolicy::default()).unwrap();

        // Falls back to using the whole ID as suffix
        let filename = logger
