            success: false,
            exit_code: Some(1),
            duration_ms: 500,
            error: Some("secret token expired".to_string()),
        });
        logger.flush().unwrap();

        let content = fs::read_to_string(logger.log_path()).unwrap();
        let value: serde_json::Value = serde_json::from_str(content.trim()).unwrap();
        assert_eq!(value["error"], "[REDACTED]");
