    #[test]
    fn log_working_directory_extracts_from_session_started() {
        let dir = TempDir::new().unwrap();
        let log_path = dir.path().join("test.jsonl");
        let line = serde_json::json!({
            "ts": "2026-04-25T10:00:00.000Z",
            "session": "sess_test",
            "type": "session_started",
            "command": "run",
            "args": [],
            "version": "1.9.0",
