257	/// Load a single config file and parse it into BivvyConfig.
258	///
259	/// # Errors
260	///
261	/// Returns `ConfigNotFound` if the file doesn't exist.
262	/// Returns `ConfigParseError` if the YAML is invalid.
263	pub fn load_config_file(path: &Path) -> Result<BivvyConfig> {
264	    let content = fs::read_to_string(path).map_err(|e| {
265	        if e.kind() == std::io::ErrorKind::NotFound {
266	            BivvyError::ConfigNotFound {
267	                path: path.to_path_buf(),
268	            }
269	        } else {
270	            BivvyError::Io(e)
271	        }
272	    })?;
273	
274	    parse_config(&content, path)
275	}
276	
277	/// Parse YAML content into BivvyConfig.
278	///
279	/// # Arguments
280	///
281	/// * `content` - The YAML content to parse
282	/// * `source_path` - Path for error reporting
283	pub fn parse_config(content: &str, source_path: &Path) -> Result<BivvyConfig> {
284	    serde_yaml::from_str(content).map_err(|e| BivvyError::ConfigParseError {
285	        path: source_path.to_path_buf(),
286	        message: e.to_string(),
287	    })
288	}
289	
290	/// Load a config file as raw YAML Value (for merging).
291	///
292	/// Returns the raw serde_yaml::Value without deserializing into
293	/// BivvyConfig, which allows for deep merging before final parsing.
294	pub fn load_config_value(path: &Path) -> Result<serde_yaml::Value> {
295	    let content = fs::read_to_string(path).map_err(|e| {
296	        if e.kind() == std::io::ErrorKind::NotFound {
297	            BivvyError::ConfigNotFound {
298	                path: path.to_path_buf(),
299	            }
300	        } else {
301	            BivvyError::Io(e)
302	        }
303	    })?;
304	
305	    serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
306	        path: path.to_path_buf(),
307	        message: e.to_string(),
308	    })
309	}
310	
311	/// Load split-file definitions and return a synthetic YAML value.
312	///
313	/// Reads each file in `paths`, wraps its content under `top_key.<stem>`,
314	/// and merges them all into one value. For example, `.bivvy/steps/database.yml`
315	/// becomes `{ steps: { database: <file content> } }`.
316	///
317	/// # Errors
318	///
319	/// Returns `ConfigParseError` if any file cannot be read or parsed.
320	fn load_split_files(paths: &[PathBuf], top_key: &str) -> Result<Option<serde_yaml::Value>> {
321	    if paths.is_empty() {
322	        return Ok(None);
323	    }
324	
325	    let mut entries = serde_yaml::Mapping::new();
326	
327	    for path in paths {
328	        let stem = path.file_stem().and_then(|s| s.to_str()).ok_or_else(|| {
329	            BivvyError::ConfigParseError {
330	                path: path.clone(),
331	                message: "Could not determine name from filename".to_string(),
332	            }
333	        })?;
334	
335	        let value = load_config_value(path)?;
336	
337	        entries.insert(serde_yaml::Value::String(stem.to_string()), value);
338	    }
339	
340	    let mut wrapper = serde_yaml::Mapping::new();
341	    wrapper.insert(
342	        serde_yaml::Value::String(top_key.to_string()),
343	        serde_yaml::Value::Mapping(entries),
344	    );
345	
346	    Ok(Some(serde_yaml::Value::Mapping(wrapper)))
347	}
348	
349	/// Parse a single workflow file into a [`WorkflowFile`], auto-detecting
350	/// new vs. legacy format.
351	///
352	/// New format: file has a top-level `workflow:` mapping. The whole file
353	/// is parsed as `WorkflowFile`.
354	///
355	/// Legacy format: no top-level `workflow:` key. The file is parsed as
356	/// `WorkflowConfig` and wrapped in a `WorkflowFile` with empty
357	/// `steps`/`vars`, preserving the workflow declaration as-is.
358	pub fn parse_workflow_file_value(
359	    value: serde_yaml::Value,
360	    source_path: &Path,
361	) -> Result<WorkflowFile> {
362	    let is_new_format = value
363	        .as_mapping()
364	        .map(|m| m.contains_key(serde_yaml::Value::String("workflow".to_string())))
365	        .unwrap_or(false);
366	
367	    if is_new_format {
368	        serde_yaml::from_value(value).map_err(|e| BivvyError::ConfigParseError {
369	            path: source_path.to_path_buf(),
370	            message: e.to_string(),
371	        })
372	    } else {
373	        let workflow: WorkflowConfig =
374	            serde_yaml::from_value(value).map_err(|e| BivvyError::ConfigParseError {
375	                path: source_path.to_path_buf(),
376	                message: e.to_string(),
377	            })?;
378	        Ok(WorkflowFile {
379	            description: workflow.description.clone(),
380	            steps: Default::default(),
381	            vars: Default::default(),
382	            workflow,
383	        })
384	    }
385	}
386	
387	/// Read a workflow file from disk and parse it into a [`WorkflowFile`].
388	///
389	/// This is the public entry point used by `bivvy lint --workflow <name>`
390	/// and discovery-based commands that want a single workflow file in
391	/// isolation, without merging anything else.
392	pub fn load_single_workflow_file(path: &Path) -> Result<WorkflowFile> {
393	    let value = load_config_value(path)?;
394	    parse_workflow_file_value(value, path)
395	}
396	
397	/// Read a step file from disk and parse it into a [`StepConfig`].
398	///
399	/// Step files are simpler than workflow files — they have only one shape.
400	pub fn load_single_step_file(path: &Path) -> Result<StepConfig> {
401	    let content = fs::read_to_string(path).map_err(|e| {
402	        if e.kind() == std::io::ErrorKind::NotFound {
403	            BivvyError::ConfigNotFound {
404	                path: path.to_path_buf(),
405	            }
406	        } else {
407	            BivvyError::Io(e)
408	        }
409	    })?;
410	    serde_yaml::from_str(&content).map_err(|e| BivvyError::ConfigParseError {
411	        path: path.to_path_buf(),
412	        message: e.to_string(),
413	    })
414	}
415	
416	/// Convert a [`WorkflowFile`] into the partial `BivvyConfig` YAML value it
417	/// contributes to the merge chain.
418	///
419	/// Produces a mapping with `vars`, `steps`, and `workflows.<stem>` keys.
420	/// The workflow's description falls back to the file-level description
421	/// when not set inside the `workflow:` block.
422	fn workflow_file_to_partial(file: &WorkflowFile, stem: &str) -> Result<serde_yaml::Value> {
423	    let mut wrapper = serde_yaml::Mapping::new();
424	
425	    if !file.vars.is_empty() {
426	        let vars_value =
427	            serde_yaml::to_value(&file.vars).map_err(|e| BivvyError::ConfigParseError {
428	                path: PathBuf::from(format!(".bivvy/workflows/{stem}.yml")),
429	                message: format!("Failed to serialize workflow vars: {e}"),
430	            })?;
431	        wrapper.insert(serde_yaml::Value::String("vars".to_string()), vars_value);
432	    }
433	
434	    if !file.steps.is_empty() {
435	        let steps_value =
436	            serde_yaml::to_value(&file.steps).map_err(|e| BivvyError::ConfigParseError {
437	                path: PathBuf::from(format!(".bivvy/workflows/{stem}.yml")),
438	                message: format!("Failed to serialize workflow steps: {e}"),
439	            })?;
440	        wrapper.insert(serde_yaml::Value::String("steps".to_string()), steps_value);
441	    }
442	
443	    let mut workflow = file.workflow.clone();
444	    if workflow.description.is_none() {
445	        if let Some(ref desc) = file.description {
446	            workflow.description = Some(desc.clone());
447	        }
448	    }
449	
450	    let workflow_value =
451	        serde_yaml::to_value(&workflow).map_err(|e| BivvyError::ConfigParseError {
452	            path: PathBuf::from(format!(".bivvy/workflows/{stem}.yml")),
453	            message: format!("Failed to serialize workflow: {e}"),
454	        })?;
455	
456	    let mut workflows_map = serde_yaml::Mapping::new();
457	    workflows_map.insert(serde_yaml::Value::String(stem.to_string()), workflow_value);
458	    wrapper.insert(
459	        serde_yaml::Value::String("workflows".to_string()),
460	        serde_yaml::Value::Mapping(workflows_map),
461	    );
462	
463	    Ok(serde_yaml::Value::Mapping(wrapper))
464	}
465	
466	/// Load every workflow file in `paths`, parse each as `WorkflowFile`
467	/// (with legacy fallback), and produce one merged partial config value.
468	fn load_split_workflow_files_all(paths: &[PathBuf]) -> Result<Option<serde_yaml::Value>> {
469	    if paths.is_empty() {
470	        return Ok(None);
471	    }
472	
473	    let partials: Vec<serde_yaml::Value> = paths
474	        .iter()
475	        .map(|path| {
476	            let stem = path.file_stem().and_then(|s| s.to_str()).ok_or_else(|| {
477	                BivvyError::ConfigParseError {
478	                    path: path.clone(),
479	                    message: "Could not determine name from filename".to_string(),
480	                }
481	            })?;
482	            let file = load_single_workflow_file(path)?;
483	            workflow_file_to_partial(&file, stem)
484	        })
485	        .collect::<Result<Vec<_>>>()?;
486	
487	    Ok(Some(merge_configs(&partials)))
488	}
489	
490	/// Collect config values in merge order, including split files.
491	///
492	/// Merge order:
493	/// 1. Remote base configs (from `extends:`)
494	/// 2. User global config (`~/.bivvy/config.yml`)
495	/// 3. Project config (`.bivvy/config.yml`)
496	/// 4. Split-file steps (`.bivvy/steps/*.yml`)
497	/// 5. Split-file workflows (`.bivvy/workflows/*.yml`) — selection
498	///    determines which files participate.
499	/// 6. Local overrides (`.bivvy/config.local.yml`)
500	fn collect_config_values(
501	    paths: &ConfigPaths,
502	    workflows: WorkflowSelection<'_>,
503	) -> Result<Vec<serde_yaml::Value>> {
504	    let mut configs = Vec::new();
505	
506	    // 1. Remote extends (populated later by resolver)
507	    for p in &paths.extends {
508	        configs.push(load_config_value(p)?);
509	    }
510	
511	    // 2. User global
512	    if let Some(p) = &paths.user_global {
513	        configs.push(load_config_value(p)?);
514	    }
515	
516	    // 3. Project config
517	    if let Some(p) = &paths.project {
518	        configs.push(load_config_value(p)?);
519	    }
520	
521	    // 4. Split-file steps
522	    if let Some(v) = load_split_files(&paths.split_steps, "steps")? {
523	        configs.push(v);
524	    }
525	
526	    // 5. Split-file workflows (selected per request)
527	    match workflows {
528	        WorkflowSelection::All => {
529	            if let Some(v) = load_split_workflow_files_all(&paths.split_workflows)? {
530	                configs.push(v);
531	            }
532	        }
533	        WorkflowSelection::One(name) => {
534	            if let Some(path) = paths.split_workflows.iter().find(|p| {
535	                p.file_stem()
536	                    .and_then(|s| s.to_str())
537	                    .is_some_and(|stem| stem == name)
538	            }) {
539	                let file = load_single_workflow_file(path)?;
540	                configs.push(workflow_file_to_partial(&file, name)?);
541	            }
542	        }
543	        WorkflowSelection::None => {}
544	    }
545	
546	    // 6. Local overrides
547	    if let Some(p) = &paths.project_local {
548	        configs.push(load_config_value(p)?);
549	    }
550	
551	    Ok(configs)
552	}
553	
554	/// Load and merge all config files for a project.
555	///
556	/// Discovers and merges configs in this order:
557	/// 1. Remote base configs (from `extends:`)
558	/// 2. User global config (`~/.bivvy/config.yml`)
559	/// 3. Project config (`.bivvy/config.yml`)
560	/// 4. Split-file steps (`.bivvy/steps/*.yml`)
561	/// 5. Split-file workflows (`.bivvy/workflows/*.yml`)
562	/// 6. Local overrides (`.bivvy/config.local.yml`)
563	///
564	/// # Errors
565	///
566	/// Returns `ConfigNotFound` if no project config exists.
567	/// Returns `ConfigParseError` if any config file is invalid.
568	pub fn load_merged_config(project_root: &Path) -> Result<BivvyConfig> {
569	    load_merged_config_with_resolver(project_root, &ExtendsResolver::default())
