            for (name, content) in workflows {
                fs::write(dir.join(format!("{name}.yml")), content).unwrap();
            }
        }
        if !steps.is_empty() {
            let dir = bivvy.join("steps");
            fs::create_dir_all(&dir).unwrap();
            for (name, content) in steps {
