/// Returns the platform-specific configuration directory.
///
/// - macOS: `$HOME/Library/Application Support`
/// - Linux: `$XDG_CONFIG_HOME` or `$HOME/.config`
/// - Windows: `%APPDATA%`
pub fn config_dir() -> Option<PathBuf> {
    if cfg!(target_os = "macos") {
        home_dir().map(|h| h.join("Library/Application Support"))
    } else if cfg!(windows) {
        std::env::var_os("APPDATA").map(PathBuf::from)
    } else {
        std::env::var_os("XDG_CONFIG_HOME")
            .map(PathBuf::from)
            .or_else(|| home_dir().map(|h| h.join(".config")))
    }
}

/// Returns the platform-appropriate directory for bivvy's persistent data.
///
/// Routes through [`data_dir`] to respect platform conventions and XDG
/// on Linux. Used by subsystems that store state, snapshots, logs,
/// registry data, and trust information.
///
/// - macOS: `$HOME/Library/Application Support/bivvy`
/// - Linux: `$XDG_DATA_HOME/bivvy` or `$HOME/.local/share/bivvy`
/// - Windows: `%APPDATA%/bivvy`
pub fn bivvy_data_dir() -> Option<PathBuf> {
    data_dir().map(|d| d.join("bivvy"))
}

/// Returns the platform-appropriate directory for bivvy's user configuration.
///
/// Routes through [`config_dir`] to respect platform conventions and XDG
